    "explanation": "「誤っているもの」を選ぶ問題。ファラデーの法則では、通過した電子の物質量が同じなら、電極で反応する物質の物質量は半反応式の電子係数に反比例する。たとえば Ag⁺ + e⁻ → Ag と Cu²⁺ + 2e⁻ → Cu では、同じ電気量に対して銀は銅の2倍の物質量が析出する。したがって、受け取る電子数に関係なく物質量が等しいとした選択肢4が誤りである。電気分解では、まず陰極＝還元、陽極＝酸化を書き、次に電子係数で量を結ぶ。",
