    "explanation": "実在気体が理想気体からずれる二つの原因を、Z ＝ PV/nRT の値の大小と結び付ける問題。理想気体は「分子自身の体積がなく、分子間力もはたらかない」仮想の気体である。実在気体では、(ア) 分子間力がはたらくと分子が引き合って体積 V が理想気体より小さくなり Z ＜ 1 に、(イ) 分子自身の体積があると分子が自由に動ける空間が減って V が理想気体より大きくなり Z ＞ 1 になる。図1では P を大きくするほど Z が 1 より大きくなる一方向のずれなので、(イ) の効果、つまり圧縮して分子が密になるほど分子自身の体積が無視できなくなることが理由である。H₂ は分子量が小さく分子間力が非常に弱いうえ、500 K は H₂ の沸点（20 K）よりはるかに高温で分子間力の影響が小さいため、(ア) による Z ＜ 1 のくぼみがほとんど現れない。「Z ＜ 1 は分子間力、Z ＞ 1 は分子自身の体積」「高温・低圧ほど理想気体に近い」の二つが判断の軸になる。",
