    "explanation": "モル濃度（溶液 1 L 当たりの溶質の物質量）と質量モル濃度（溶媒 1 kg 当たりの溶質の物質量）の定義の違いを、「温度で変わるか」「溶液の体積は水の体積と同じか」の2点から問う問題。液体の体積は温度で変わる（温めると膨張する）ので、溶液の体積を基準にするモル濃度は温度とともに変化する（①は正しい）。一方、質量は温度で変わらないので、溶媒の質量を基準にする質量モル濃度は温度によらず一定である（②は正しい）。沸点上昇や凝固点降下は温度を変えながら測る実験なので、温度で変わらない質量モル濃度を使う、という冒頭の一文がそのまま①・②の根拠になる。③は、1 mol/kg なら溶質の種類によらず「水 1 kg（1000/18 mol）に溶質 1 mol」なので、溶質と水の物質量の比は同じである（正しい）。④が誤り。問題文に「水溶液の体積は水の体積に比べて増加する」とあるので、1 mol/L のショ糖水溶液 1 L は「水 1 L ＋ ショ糖 1 mol」ではなく、1 L に満たない水にショ糖を溶かして全体を 1 L にしたものである。したがって含まれる水は 1 L より少なく、その物質量は 1 L の水の物質量より小さい。「モル濃度は溶液の体積、質量モル濃度は溶媒の質量」という基準の違いを押さえれば、④の引っかけ（溶液 1 L ＝ 水 1 L と思い込む）を避けられる。",
