    "explanation": "「反応速度」と「平衡時の物質量」を分けて考え、グラフの立ち上がりと到達点の両方を判断する問題。容器の体積を2倍にすると、H₂・I₂ の物質量は同じでもモル濃度はそれぞれ 1/2 になる。正反応の速度は v₁ ＝ k₁[H₂][I₂] なので、反応の初めの速度は 1/2 × 1/2 ＝ 1/4 になり、HI の増え方はもとの実験より遅くなる（立ち上がりがゆるやか）。一方、平衡時の物質量は、この反応が H₂ ＋ I₂ ⇄ 2 HI で両辺の気体の分子数が等しい（2 ＝ 2）ため、体積を変えても平衡は移動しない。平衡定数 K ＝ [HI]²/([H₂][I₂]) では分子・分母のモル濃度の次数が同じで体積の影響が打ち消されるからで、平衡時の HI の物質量はもとの実験と同じ 0.8 mol になる。したがって「遅く増えて同じ 0.8 mol に近づく」③が正解。①は速く、⑤は同じ速さで、②・④は到達点が違うので合わない。「分子数の変わらない反応は圧力（体積）を変えても平衡は動かないが、濃度が下がるぶん速度は遅くなる」という、平衡と速度の使い分けが決め手である。",
