    "explanation": "「塩の水溶液の液性」と「化学式の中の結合」を二段階で切る問題。まず液性は、その塩をつくる酸と塩基の強弱で決まる。弱酸＋強塩基の塩は塩基性、強酸＋弱塩基の塩は酸性、強酸＋強塩基の塩は中性である。硫化ナトリウム Na₂S は弱酸 H₂S と強塩基 NaOH の塩、乳酸ナトリウム CH₃CH(OH)COONa は弱酸の乳酸と NaOH の塩なので、どちらも水溶液は塩基性（S²⁻ や乳酸イオンが加水分解して OH⁻ を生じる）。塩化アンモニウム NH₄Cl は強酸 HCl と弱塩基 NH₃ の塩で酸性、塩化カルシウム CaCl₂ は強酸と強塩基の塩で中性なので、アの時点で①・④が外れる。次に二重結合の有無を見ると、乳酸ナトリウムはカルボキシ基由来の －COO⁻ に C＝O の二重結合をもつ。硫化ナトリウムは Na⁺ と S²⁻ からなるイオン結晶で、共有結合そのものがなく二重結合もない。したがって両方に当てはまるのは②の硫化ナトリウムである。「塩基性の塩は弱酸の塩」「有機酸の塩には必ず C＝O がある」の2点で選べる。",
