      "正解。硫化ナトリウム Na₂S は弱酸 H₂S と強塩基 NaOH の塩で、S²⁻ ＋ H₂O ⇄ HS⁻ ＋ OH⁻ の加水分解により水溶液は塩基性を示す（ア）。Na⁺ と S²⁻ からなるイオン結晶で、分子内に共有結合がなく二重結合ももたない（イ）。",
