    "answer": 1,
    "explanation": "分子からなる物質の沸点を決める分子間力の3つの要因――「分子量（ファンデルワールス力）」「極性」「水素結合」――と、溶液の沸点上昇の原因を正しく説明できるかを問う問題。②の HCl と F₂ は分子量がほぼ同じ（36.5 と 38）なのに HCl の沸点のほうが高い。その理由は HCl が極性分子で、分子間に静電的な引力（極性による分子間力）が加わるからである。選択肢は「極性が小さくなると分子間力が強くはたらく」と因果が逆になっているので、②が誤り。正しくは「分子の極性が大きくなると分子間力が強くはたらくため」。①は同族の無極性分子どうしなら分子量が大きいほどファンデルワールス力が強く沸点が高い、③は H₂O だけが水素結合をつくるので同族で異常に沸点が高い、④は不揮発性の溶質が溶けると蒸気圧が下がる（蒸気圧降下）ため、蒸気圧が大気圧に達する温度、すなわち沸点が高くなる、といずれも正しい説明である。「分子量 → ファンデルワールス力」「極性 → 静電引力」「H が F・O・N に結合 → 水素結合」の3段で沸点を比べる型を身につける。",
