    "stemTitle": "問題文（ヘキサンとメタノールの混合）",
    "stem": "ある温度において一定量のメタノールにヘキサンを追加・撹拌・静置する一連の操作を繰り返すと、ヘキサンが少量のうちは混ざり合った均一溶液であるが、さらに追加すると二層の溶液に分離する。二層に分離するときは、密度の違いにより、上層はヘキサンにメタノールが飽和した溶液、下層は逆にメタノールにヘキサンが飽和した溶液になる。この混合溶液が均一溶液になるか二層に分離するかは温度にも依存し、さらに高い温度では、ヘキサンとメタノールは任意の割合で均一に混ざり合う。",
    "question": "ヘキサンやメタノールの性質の記述として、誤りを含むものはどれか。最も適当なものを、次のうちから一つ選べ。",
    "choices": [
      "ヘキサンは、無極性分子である。",
      "メタノールは、極性分子である。",
      "室温でヘキサンは、水にほとんど溶けない。",
      "室温で水とメタノールは、混合する割合によっては二層に分離する。"
    ],
    "answer": 3,
    "explanation": "「極性の似たものどうしはよく溶け合う」という溶解の基本原則を、ヘキサン・メタノール・水の3つで確かめる問題。ヘキサン C₆H₁₄ は C と H だけからなる炭化水素で、C－H 結合の極性はごく小さく分子全体として無極性である（①は正しい）。メタノール CH₃OH は電気陰性度の大きい O をもつヒドロキシ基 －OH があり、O－H 結合の極性が分子全体の極性となる極性分子である（②は正しい）。極性のない ヘキサンは、水素結合で強く結びついた極性分子の水には割り込めず、ほとんど溶けない（③は正しい）。一方、メタノールは －OH が水と水素結合をつくれるので、水とは任意の割合で均一に混ざり合い、二層に分離することはない。したがって④が誤り。「炭化水素基が小さいアルコール（メタノール・エタノール・1-プロパノール）は水と自由に混ざる」「炭素数が増えるほど水に溶けにくくなる」という知識で判断する。問題文のヘキサン－メタノールの二層分離は、片方が無極性・片方が極性という組合せだから起こる現象で、水－メタノール（どちらも極性で水素結合をつくる）とは事情が違う。",
    "choiceNotes": [
      "正しい。ヘキサン C₆H₁₄ は C と H だけからなる鎖状の炭化水素で、C－H の極性は小さく、分子全体として電荷のかたよりがない無極性分子である。",
      "正しい。メタノール CH₃OH はヒドロキシ基 －OH をもち、電気陰性度の大きい O に電子がかたよる。分子は折れ線形の O まわりの構造をもち、極性が打ち消されないので極性分子である。",
      "正しい。無極性のヘキサンは、水分子どうしの水素結合の中に入り込めず、水とは混ざらない。水面にヘキサンの層ができ、二層に分離する（ヘキサンは水より密度が小さいので上層）。",
      "誤り。メタノールは －OH をもち、水分子と水素結合をつくれるので、室温でどんな割合でも水と均一に混ざり合い、二層に分離することはない。正しくは「室温で水とメタノールは、任意の割合で均一に混ざり合う」。炭化水素基の大きい 1-ブタノール以上のアルコールになると水に溶けにくくなる。"
    ],
