    "explanation": "電気を通すには「自由に動ける電荷の担い手（イオンまたは自由電子）」が必要である。この観点で5つを分けると、アセトンと1 mol/L のグルコース水溶液は分子のまま存在する非電解質で、イオンがほとんどないため電気を通さない。塩化ナトリウムはイオン結晶だが、固体ではイオンが格子に固定されて動けないので通さない（融解させるか水に溶かすと通す）。残る酢酸水溶液と塩酸はどちらも電解質の水溶液だが、酢酸は弱酸で 1 mol/L では電離度が約 0.4 ％程度にすぎず、塩酸（塩化水素）は強酸でほぼ完全に電離している。同じ 1 mol/L ならイオンの濃度は塩酸のほうがはるかに大きく、電気を最もよく通すのは④の 1 mol/L の塩酸である。「電解質か非電解質か」「固体か溶液か」「強電解質か弱電解質か」の三段階で絞るのが定石で、最後の段階で電離度の差を思い出せるかがポイントになる。",
    "choiceNotes": [
      "誤り。アセトン CH₃COCH₃ は極性のある分子性物質だが、電離してイオンを生じることはなく非電解質である。液体でも電気をほとんど通さない。",
      "誤り。グルコース C₆H₁₂O₆ は水によく溶けるが分子のまま溶けている非電解質で、水溶液中にイオンがほとんどないため電気を通さない。「水に溶ける」ことと「電離する」ことは別である。",
      "誤り。酢酸は電解質だが弱酸で、1 mol/L 水溶液での電離度は 1 ％に満たない（約 0.4 ％）。イオンの濃度が小さいので、同じ濃度の塩酸に比べると電気を通す力ははるかに弱い。",
      "正解。塩化水素 HCl は強酸で、水溶液中ではほぼ完全に H⁺（H₃O⁺）と Cl⁻ に電離している。同じ 1 mol/L の酢酸水溶液に比べてイオンの濃度が桁違いに大きく、5つの中で最も電気をよく通す。",
      "誤り。塩化ナトリウムは Na⁺ と Cl⁻ からなるイオン結晶で、電荷の担い手はもっているが、固体の状態ではイオンが結晶格子に固定されて動けないため電気を通さない。融解した液体や水溶液にすると通すようになる。"
    ],
