    "explanation": "分子の構造式（電子式）を思い浮かべて、多重結合の有無を判断する問題。原子の結合の手の数（H は1本、ハロゲンは1本、O は2本、N は3本、C は4本）を満たすように結合を組めば、どこに多重結合が要るかが決まる。シアン化水素 HCN は H－C≡N で、炭素の4本の手のうち1本を水素に使い、残る3本をすべて窒素との結合に使うので、炭素と窒素の間は三重結合になる（窒素には非共有電子対が1組残り、分子は直線形）。フッ素 F₂ は F－F の単結合、アンモニア NH₃ は N－H の単結合3本、シクロヘキセン C₆H₁₀ は六員環の中に C＝C 二重結合を1つもつだけで、いずれにも三重結合はない。三重結合をもつ身近な分子は、窒素 N₂（N≡N）、アセチレン C₂H₂（H－C≡C－H）、シアン化水素 HCN、一酸化炭素 CO（配位結合を含む C≡O）の4つを覚えておくとよい。",
