    "explanation": "反応速度を大きくする4つの要因（濃度・温度・表面積・触媒）を、それぞれ具体的な反応で確認する問題。反応が起こるには、粒子どうしが衝突し、しかも活性化エネルギー以上のエネルギーをもっていなければならない。濃度を高くすると衝突の回数が増え（①）、温度を上げると活性化エネルギーを超えるエネルギーをもつ分子の割合が急に増え（②）、固体を細かくすると反応できる表面積が増える（③）ので、いずれも反応速度は大きくなる。触媒は、活性化エネルギーの小さい別の反応経路をつくることで反応速度を大きくする物質である。したがって④の「活性化エネルギーが大きくなるので」は逆で、正しくは「活性化エネルギーが小さくなるので反応速度が大きくなる」。なお、触媒は反応熱や平衡定数（平衡の位置）を変えず、平衡に達するまでの時間を短くするだけである。この「触媒は活性化エネルギーを下げるが反応熱は変えない」は、エネルギー図とセットで最頻出の引っかけである。",
