    "explanation": "緩衝液のしくみを、加えた H⁺・OH⁻ が何に消費されるかで説明する問題。NH₃ と NH₄Cl の混合水溶液には、弱塩基 NH₃ とその共役酸 NH₄⁺ がどちらも多量に含まれている。少量の塩酸を加えると、H⁺ は弱塩基 NH₃ と反応して NH₄⁺ になる（NH₃ ＋ H⁺ → NH₄⁺）ので、H⁺ はほとんど増えない。少量の NaOH 水溶液を加えると、OH⁻ は NH₄⁺ と反応して NH₃ と H₂O になる（NH₄⁺ ＋ OH⁻ → NH₃ ＋ H₂O）ので、OH⁻ もほとんど増えない。したがってア＝NH₃、イ＝NH₄⁺、ウ＝H₂O。「H⁺ を受け取るのは弱塩基（NH₃）、OH⁻ を受け取るのは共役酸（NH₄⁺）」と、酸には塩基が、塩基には酸が応じる、という対の関係で覚えるとよい。弱酸とその塩（CH₃COOH ＋ CH₃COONa）の緩衝液でも同じ考え方で、H⁺ は CH₃COO⁻ が、OH⁻ は CH₃COOH が受け取る。",
