    "stem": "水に溶かすと泡の出る入浴剤（試料 X）には、炭酸水素ナトリウム NaHCO₃、炭酸ナトリウム Na₂CO₃、コハク酸 HOOC(CH₂)₂COOH、およびコハク酸以外の有機化合物が含まれている。試料 X に塩酸を十分に加えると、次の中和反応が起きて CO₂ が発生する。\n\nNaHCO₃ ＋ HCl → NaCl ＋ H₂O ＋ CO₂　…(1)\nNa₂CO₃ ＋ 2HCl → 2NaCl ＋ H₂O ＋ CO₂　…(2)\n\nコハク酸は2価のカルボン酸であるが、1段階目と2段階目の電離定数が同程度であるため、NaOH 水溶液による滴定曲線は見かけ上1段階となる。このことを踏まえて、試料 X に含まれるコハク酸の量を求めるために、次の実験Ⅲを行った。ただし、この試料に含まれているコハク酸以外の有機化合物は、中和反応に関係しないものとする。\n\n実験Ⅲ　10.00 g の試料 X に (a)〔塩酸を十分に加えて〕、式(1)・(2)の反応を完了させて水溶液を得た。コハク酸が分解しない温度でこの水溶液を加熱し、乾燥したのち、(b)〔水を加えてさらに加熱・乾燥することを繰り返して〕塩化水素を除去し、NaCl とコハク酸を含む固体を得た。この固体に (c)〔水を加えて溶かし〕、水溶液 Y を得た。\n次に、(d)〔1.00 mol/L の NaOH 水溶液を調製し〕、これによりフェノールフタレインを指示薬として水溶液 Y の中和滴定を行った。",
