    "explanation": "中和滴定の結果が「小さく」出る誤差の原因を、操作ごとに考える問題。この実験では、水溶液 Y 中の酸（コハク酸）を NaOH で滴定し、NaOH の滴下量 × 1.00 mol/L からコハク酸の物質量を計算する。したがって、滴下量が本来より少なくなる操作が「小さく求まる」原因である。①：塩酸が不足すると NaHCO₃ や Na₂CO₃（塩基）が残り、これらが水溶液 Y 中でコハク酸の一部を中和してしまうので、NaOH で滴定される酸が減り、滴下量が少なくなる → 小さく求まる。②：塩化水素（強酸）が残ると、それも NaOH を消費するので滴下量が増え、大きく求まる。③：水の量を変えても酸の物質量は変わらないので、滴下量は変わらない（濃度は変わるが滴定で測るのは物質量）。④：実際の濃度が 1.00 mol/L より低いと、同じ物質量の酸を中和するのに滴下量が多く要る。それを 1.00 mol/L として計算すれば、コハク酸は大きく求まる。よって①が正解。「滴定量が減る → 小さく」「滴定量が増える → 大きく」「希釈は物質量を変えない」の3点で切る。",
