    "explanation": "ルシャトリエの原理（平衡移動の原理）を、温度・圧力・濃度の三つの条件で確かめる定番問題。反応 2NO₂ ⇄ N₂O₄ は、右向きが発熱（＋57 kJ）で、右向きに進むと気体の分子数が 2 → 1 に減る。①正反応は熱化学方程式の右辺に ＋57 kJ とあるので発熱反応。②加熱すると、熱を吸収する方向（吸熱の逆反応、左向き）へ平衡が移動して NO₂ が増える。③温度一定で体積を半分にすると圧力が上がるので、気体の分子数が減る方向（右向き）へ平衡が移動し、NO₂ の分子数は減少する。「増加する」は誤りで、これが答え。④NO₂ を加えると、それを減らす方向（右向き）へ移動して N₂O₄ が増え、体積一定なので N₂O₄ の濃度も増える。⑤平衡状態は正反応と逆反応の速度が等しい動的平衡。③で注意したいのは、体積を半分にした直後には NO₂ の濃度（mol/L）は 2 倍になり、平衡移動後も圧縮前より濃度は高いが、分子数（物質量）そのものは減るという点である。「濃度」と「分子数」を区別して読む。",
