    "explanation": "水酸化ナトリウムの工業的製法である陽イオン交換膜法（イオン交換膜法）を問う問題。塩化ナトリウム水溶液の電気分解では、陽極（炭素）では Cl⁻ が酸化されて塩素が発生し（2Cl⁻ → Cl₂ ＋ 2e⁻）、陰極（白金）では Na⁺ は還元されにくいので代わりに水が還元されて水素が発生し、OH⁻ が生じる（2H₂O ＋ 2e⁻ → H₂ ＋ 2OH⁻）。陽イオン交換膜は陽イオンだけを通す膜なので、陽極側で余った Na⁺ が陰極側へ移動し、陰極側に NaOH がたまる。よって「塩素・水素・ナトリウムイオン」の ④ が正しい。膜で仕切る理由は、陰極側にできた OH⁻ が陽極側に移って塩素と反応してしまう（Cl₂ ＋ 2OH⁻ → Cl⁻ ＋ ClO⁻ ＋ H₂O）のを防ぎ、純度の高い NaOH を得るためである。「陽極では陰イオンが酸化される（Cl⁻ ＞ OH⁻ の順に反応しやすい）」「陰極では Na⁺ のようなイオン化傾向の大きい金属イオンの代わりに水が還元されて H₂ が出る」という電気分解の原則も合わせて確認しておく。",
