    "explanation": "純溶媒の冷却曲線の各部分が何を表すかを問う問題。液体を冷やしていくと、凝固点 T に達してもすぐには固体が現れず、液体のまま T より低い温度まで下がることがある（過冷却）。図2の点 A はこの過冷却の途中である。曲線の極小点で最初の結晶が生じて凝固が始まると、凝固熱（融解熱と同じ大きさ）が放出されて温度は T まで急に戻り（極小点から B まで）、その後は液体がすべて固体になるまで、放出される凝固熱と冷却で奪われる熱がつり合って温度 T で一定になる（B〜D、液体と固体が共存）。D で全部が固体になると、固体の冷却に移って再び温度が下がる。したがって凝固が始まったのは B ではなく、B より前の極小点なので ③ が誤り。B は「凝固熱で温度が凝固点まで戻った点」である。⑤は溶液の冷却曲線との比較で、少量の溶質を溶かすと凝固点降下によって凝固の始まる温度が T より低くなり、しかも凝固が進むほど溶液が濃くなって温度が下がり続けるので、D に相当する（凝固が終わる）状態の温度は純溶媒より低い。「過冷却の極小点で凝固が始まる」「水平部分は固液共存」「溶液では水平にならず右下がり」の 3 点を押さえる。",
