      "正解。滴定前の pH が約 3 なのは、0.10 mol/L でも電離度が小さい弱酸（酢酸）だからである（強酸の塩酸なら pH 1）。中和点を過ぎて pH が 13 近くまで上がるのは強塩基の水酸化ナトリウムだからで、中和点が塩基性側（pH 8〜9）にあるのも酢酸ナトリウムの加水分解と合う。",
      "誤り。酸が酢酸なのは滴定前の pH 約 3 と合うが、塩基がアンモニア水（弱塩基）なら、過剰に加えても pH は 11 前後までしか上がらず、pH の急上昇もはっきりしない。図では 40 mL で pH が 13 に近づいているので、塩基は強塩基の水酸化ナトリウムである。",
      "誤り。塩基が水酸化ナトリウムなのは滴定後の pH と合うが、酸が 0.10 mol/L の塩酸なら滴定前の pH は 1 になるはずで、図の約 3 とは合わない。強酸と強塩基の滴定なら、pH の急上昇は約 3 から約 11 までと広く、中和点は pH 7 になる。",
      "誤り。塩酸なら滴定前の pH は 1（図は約 3）、アンモニア水なら滴定後の pH は 11 前後まで（図は 13 近く）で、どちらも図と合わない。強酸と弱塩基の組合せでは、中和点は酸性側（pH 5〜6）にくる。"
