    "explanation": "同素体の定義を正しくつかんでいるかを問う問題。同素体とは「同じ元素からできている単体で、原子の結びつき方が違うために性質が異なるもの」をいう。単体どうしの関係であることが第一の条件で、化合物どうしや原子どうしの関係には使わない。⑥の黄リンと赤リンは、どちらもリン P だけからなる単体で、黄リン P₄ は正四面体形の分子からなり猛毒・自然発火性で水中に保存し、赤リンは多数の P 原子が網目状につながった固体で毒性が低くマッチの側薬に使われる。同じ元素の単体で性質が違うので同素体であり、⑥が正解。同素体をもつ代表的な元素は硫黄 S（斜方硫黄・単斜硫黄・ゴム状硫黄）、炭素 C（ダイヤモンド・黒鉛・フラーレン・カーボンナノチューブ）、酸素 O（酸素 O₂・オゾン O₃）、リン P（黄リン・赤リン）で、頭文字をとって「スコップ（SCOP）」と覚える。引っかけになるのは②で、³⁵Cl と ³⁷Cl のように同じ元素で中性子の数（質量数）が異なる「原子」どうしの関係は同位体（アイソトープ）といい、同素体とは別の言葉である。「同素体は単体、同位体は原子」と区別する。",
