    "stemTitle": "問題文（アルミニウムの工業的製造法）",
    "stem": "アルミニウム Al の工業的製造法に関する次の文章を読み、後の問いに答えよ。\n\n原料であるボーキサイトは、Al₂O₃·nH₂O を主成分とし、SiO₂ や Fe₂O₃ を含むので、Al₂O₃ を取り出す必要がある。\n\nボーキサイトの粉末を、加熱した高濃度の水酸化ナトリウム NaOH 水溶液に混ぜると、溶解しない化合物と、テトラヒドロキシドアルミン酸イオン [Al(OH)₄]⁻ を含む溶液に分離できる。(a)〔[Al(OH)₄]⁻ を含む溶液に二酸化炭素 CO₂ の気体を通じる〕と、(b)〔水酸化アルミニウム Al(OH)₃ の沈殿が生じる〕。沈殿として取り出した (c)〔Al(OH)₃ を加熱することで Al₂O₃ が得られる〕。\n\n得られた (d)〔Al₂O₃ を氷晶石 Na₃AlF₆ とともに約 1000 ℃ で融解させ〕、溶融塩（融解塩）電解することで、Al を得ることができる。",
    "question": "問題文の下線部 (a)〜(d)（〔　〕内が下線部）に関連した記述が、それぞれ次の①〜④に示されている。①〜④の〔　〕内の部分（原本の下線部）に誤りを含むものはどれか。最も適当なものを一つ選べ。",
