    "explanation": "窒素の単体と化合物について、教科書の基本事項を一つずつ確かめる問題。①：窒素の沸点は －196 ℃ で、大気圧下でも冷却すれば液体窒素になる（冷却剤として広く使われる）ので誤り。②：濃硝酸で不動態になるのは Al・Fe・Ni・Cr・Co などで、銀は濃硝酸に溶けて硝酸銀になるので誤り。③：オストワルト法の最終段階で、二酸化窒素を水に吸収させると 3NO₂ ＋ H₂O → 2HNO₃ ＋ NO の反応で硝酸が得られるので正しい。④：配位結合は配位子（NH₃）の非共有電子対が金属イオン（Zn²⁺）の空の軌道に提供されてできるもので、電子対の向きが逆なので誤り。よって③が正解。「不動態になる金属」「配位結合は配位子から金属へ」「NO₂ ＋ 水 → HNO₃ ＋ NO」はどれも頻出の確認事項である。",
