    "explanation": "固体の混合物 Ag・MgCl₂・AgCl から、溶解性の違いを利用して Ag だけを残す操作を選ぶ問題。MgCl₂ は水に溶けるので、まず水洗で取り除ける。AgCl は水には溶けないが、アンモニア水には AgCl ＋ 2NH₃ → [Ag(NH₃)₂]⁺ ＋ Cl⁻ と錯イオンをつくって溶ける。単体の Ag はどちらにも溶けない。したがって「水洗した後にアンモニア水で洗う」④で Ag だけが残る。水酸化ナトリウム水溶液では AgCl は溶けず、かえって褐色の酸化銀 Ag₂O に変わって固体として残るうえ、②のように先に加えると MgCl₂ から水に溶けない Mg(OH)₂ が沈殿してしまう。温水（①）では MgCl₂ しか除けない。「AgCl はアンモニア水・チオ硫酸ナトリウム水溶液・シアン化カリウム水溶液に錯イオンをつくって溶ける」「Ag⁺ に NaOH を加えると AgOH ではなく Ag₂O の褐色沈殿」の2つは、銀の化合物の定番の知識である。",
