    "explanation": "代表的な錯イオンの生成反応・色・立体構造を問う問題。錯イオンの形は配位数で決まり、配位数 2（[Ag(NH₃)₂]⁺）は直線形、配位数 6（[Fe(CN)₆]³⁻・[Fe(CN)₆]⁴⁻）は正八面体形である。配位数 4 は金属によって違い、[Zn(NH₃)₄]²⁺ は正四面体形、[Cu(NH₃)₄]²⁺ は正方形になる。したがって④の「正方形」が誤りで、正しくは正四面体形。①は Cu(OH)₂ の青白色沈殿が過剰のアンモニア水に溶けて深青色の [Cu(NH₃)₄]²⁺ になる反応、②は Ag₂O の褐色沈殿が溶けて無色の [Ag(NH₃)₂]⁺ になる反応で、どちらも金属イオンの分離・検出で使う。③はヘキサシアニド鉄(Ⅱ)酸イオンと Fe³⁺ から濃青色沈殿（紺青）が生じる Fe³⁺ の検出反応である。「Zn は正四面体、Cu は正方形」の対比が最頻出の引っかけで、亜鉛の錯イオンは無色、銅の錯イオンは深青色という色の違いとセットで覚える。",
