    "explanation": "遷移元素が触媒としてはたらく代表的な反応を、工業的製法を中心にまとめた問題。誤りは ② で、ハーバー・ボッシュ法は N₂ ＋ 3H₂ ⇄ 2NH₃ の平衡を右へ寄せるために、四酸化三鉄 Fe₃O₄ を主成分とする触媒を使って約 400〜600 ℃、数百気圧（2〜5×10⁷ Pa 程度）の高圧で反応させる。「常圧」が誤り。ほかは正しい。①鉄粉（実際には生じる FeCl₃）を触媒にベンゼンと塩素を反応させると、置換反応でクロロベンゼンができる。③接触法は、V₂O₅ を触媒に SO₂ を SO₃ にし、SO₃ を濃硫酸に吸収させて発煙硫酸とし、それを希硫酸で薄めて濃硫酸にする（SO₃ を直接水に入れると激しく発熱して霧になるため）。④オストワルト法は、Pt 触媒で NH₃ を NO に酸化し、NO → NO₂ → HNO₃ と進める。⑤三元触媒は Pt・Pd・Rh で、CO・炭化水素・NOx を CO₂・H₂O・N₂ に変える。工業的製法は「触媒・温度・圧力・中間物質」を一組にして覚える。アンモニアの合成が高圧なのは、分子数が減る反応（4 → 2）だからである。",
