    "explanation": "アンモニアソーダ法（ソルベー法）の流れを問う問題。図1の上の経路で、NaCl の飽和水溶液にアンモニアを溶かして二酸化炭素を通じると、水に溶けにくい炭酸水素ナトリウムが沈殿する（NaCl ＋ NH₃ ＋ CO₂ ＋ H₂O → NaHCO₃ ＋ NH₄Cl）。これが化合物 A ＝ NaHCO₃ である。炭酸水素ナトリウムは熱に弱く、加熱すると熱分解して炭酸ナトリウムになる（2NaHCO₃ → Na₂CO₃ ＋ H₂O ＋ CO₂）。この熱分解が〔 4 〕の操作なので ③「加熱する」が正解。発生した CO₂ は回収して再び NaCl 水溶液に通じ、NH₄Cl は石灰石を焼いてできた CaO（Ca(OH)₂）と反応させて NH₃ を回収するのがアンモニアソーダ法の特徴である。「NaHCO₃ は加熱で Na₂CO₃ に、Na₂CO₃ は加熱しても分解しない」「重曹（ふくらし粉）が加熱で CO₂ を出すのも同じ反応」と結びつけておく。",
