    "explanation": "硫黄の化合物の製法と性質、とくに二酸化硫黄の酸化還元でのはたらきを問う問題。二酸化硫黄 SO₂（S の酸化数 ＋4）はふつう還元剤としてはたらき（＋4 → ＋6）、過酸化水素や過マンガン酸カリウムなどを還元する。しかし相手が硫化水素 H₂S（S の酸化数 −2）のような強い還元剤のときは、SO₂ のほうが酸化剤としてはたらき、2H₂S ＋ SO₂ → 3S ＋ 2H₂O のように硫黄が遊離する（SO₂ の S は ＋4 → 0、H₂S の S は −2 → 0）。したがって「二酸化硫黄が還元剤」は誤りで、② が正解。①硫黄を空気中で燃やすと S ＋ O₂ → SO₂。②の反応は還元剤の強さが H₂S ＞ SO₂ であることを表す。③接触法では、酸化バナジウム(Ⅴ) V₂O₅ を触媒として 2SO₂ ＋ O₂ → 2SO₃ とし、SO₃ を濃硫酸に吸収させて発煙硫酸にしてから希釈して硫酸をつくる。④硫化水素は水に少し溶け、H₂S ⇌ H⁺ ＋ HS⁻ とわずかに電離する弱酸（2 価）である。⑤鉛蓄電池は負極 Pb、正極 PbO₂、電解液は希硫酸で、放電すると負極では Pb → PbSO₄、正極では PbO₂ → PbSO₄ となり、両極の表面に水に溶けにくい硫酸鉛(Ⅱ) PbSO₄ が付着する。「SO₂ はふつう還元剤、ただし H₂S に対しては酸化剤」は頻出の例外で、酸化数（−2・0・＋4・＋6）の並びで整理して覚える。",
