      "誤り。Pb²⁺ は操作Ⅰの塩酸で PbCl₂ として沈殿するので、沈殿 b には入らない。また Cu²⁺ は操作Ⅱの硫化水素で CuS として沈殿 b になるので、沈殿 c にはならない（仮に残っていても過剰のアンモニア水には [Cu(NH₃)₄]²⁺ となって溶ける）。",
