    "explanation": "酸化物を酸性酸化物・塩基性酸化物・両性酸化物に分類し、それぞれが酸・塩基のどちらと反応するかを問う問題。酸化物は元素の種類でおおむね分類できる。（ⅰ）非金属元素の酸化物（CO₂、SO₂、SO₃、NO₂、P₄O₁₀、SiO₂ など）は酸性酸化物で、水に溶けると酸になり、塩基と反応して塩をつくる。（ⅱ）金属元素の酸化物（Na₂O、K₂O、MgO、CaO、CuO、Fe₂O₃ など）は塩基性酸化物で、酸と反応して塩をつくる（酸とだけ反応し、塩基とは反応しない）。（ⅲ）両性元素（Al、Zn、Sn、Pb）の酸化物 Al₂O₃、ZnO、SnO、PbO は両性酸化物で、酸とも強塩基とも反応して塩をつくる。「強塩基の水溶液と反応して塩をつくる」のは酸性酸化物と両性酸化物なので、非金属 P の酸化物 ③ P₄O₁₀（十酸化四リン。水酸化ナトリウムと反応して P₄O₁₀ ＋ 12NaOH → 4Na₃PO₄ ＋ 6H₂O）と、両性酸化物 ⑤ ZnO（酸化亜鉛。ZnO ＋ 2NaOH ＋ H₂O → Na₂[Zn(OH)₄]、テトラヒドロキシド亜鉛(Ⅱ)酸ナトリウム）の 2 つが正解。① Na₂O、② MgO、④ CaO はいずれも典型金属（1 族・2 族）の酸化物で塩基性酸化物なので、塩基とは反応しない（Na₂O、CaO は水と反応して強塩基 NaOH、Ca(OH)₂ になる）。両性元素は「ああすんなり（Al・Zn・Sn・Pb）」と覚え、その単体・酸化物・水酸化物はすべて酸とも強塩基とも反応することを押さえておく。",
