    "explanation": "気体の性質（水への溶けやすさと空気に対する重さ）から捕集方法を選ぶ問題。捕集法は次の順で決める。まず「水に溶けにくい気体」（H₂、O₂、N₂、CO、NO、CH₄、C₂H₄ など）は、空気が混じらず純粋に集められる水上置換が最もよい。「水に溶けやすい気体」は水上置換が使えないので、空気より軽ければ上方置換（NH₃ だけ）、空気より重ければ下方置換（Cl₂、HCl、SO₂、NO₂、H₂S、CO₂ など）にする。塩素 Cl₂ は分子量 71 で空気の平均分子量 29 よりはるかに重く、しかも水に溶ける（一部は Cl₂ ＋ H₂O ⇄ HCl ＋ HClO と反応する）ので、水上置換では失われ、上方置換では空気より重いためたまらない。したがって下方置換が最もよく、②が正解。空気より重い気体を集めるときは、容器の口を上に向け、ガラス管を容器の底まで差し込んで下からためる。「水上置換 → 溶けにくい気体、上方置換 → アンモニアだけ、下方置換 → 水に溶けて重い気体」という 3 分類と、塩素は黄緑色・刺激臭・有毒で下方置換、という性質の組合せは頻出である。なお図1のように水の洗気びんを通しても、塩素は水への溶解度が小さいので大部分は通り抜ける（水に溶けやすい HCl が除かれる）。",
