    "explanation": "アンモニアソーダ法（ソルベー法）の流れ図を読み、各段階の物質と量的関係を判断する問題。図1の化合物 A はアンモニア NH₃、化合物 B は二酸化炭素 CO₂ である。各段階の反応は、（1）NaCl ＋ NH₃ ＋ CO₂ ＋ H₂O → NaHCO₃ ＋ NH₄Cl、（2）2NaHCO₃ → Na₂CO₃ ＋ H₂O ＋ CO₂、（3）CaCO₃ → CaO ＋ CO₂、（4）CaO ＋ H₂O → Ca(OH)₂、（5）2NH₄Cl ＋ Ca(OH)₂ → 2NH₃ ＋ CaCl₂ ＋ 2H₂O で、NH₃ と CO₂ は回収して再利用する。誤りは⑤。これらをまとめると、途中で回収される NH₃・CO₂・H₂O・CaO・Ca(OH)₂・NaHCO₃・NH₄Cl が消え、全体の反応は 2NaCl ＋ CaCO₃ → Na₂CO₃ ＋ CaCl₂ となる。したがって必要な CaCO₃ の物質量は NaCl の 1/2 で、等しくはない。ほかは正しく、① NH₃ は水に非常によく溶け、NH₃ ＋ H₂O ⇄ NH₄⁺ ＋ OH⁻ で弱塩基性を示す。② CO₂ を石灰水に通じると Ca(OH)₂ ＋ CO₂ → CaCO₃ ＋ H₂O で白色の CaCO₃ が生じて白濁する（CO₂ の検出反応）。③ NaCl の飽和水溶液に NH₃ を十分に溶かしてから CO₂ を通じると、溶解度の比較的小さい NaHCO₃ が沈殿する。これがアンモニアソーダ法の中心の反応である。④ 窒素を含む化合物は NH₃（A）と NH₄Cl だけで、（1）で NH₃ が NH₄Cl になり、（5）で NH₄Cl が NH₃ に戻るだけなので、両者の物質量の合計は変化しない（窒素原子は系の外に出ない）。全体の式 2NaCl ＋ CaCO₃ → Na₂CO₃ ＋ CaCl₂ と、「NH₃ と CO₂ は循環して再利用、原料は NaCl と CaCO₃ だけ」を押さえておく。",
