    "explanation": "「誤っているもの」を選ぶ問題。メタンは飽和炭化水素で炭素間二重結合をもたないため、臭素の付加反応は起こらない。また、アルカンのハロゲン化は光や加熱を開始条件とするラジカル置換反応であり、暗所の臭素水とは速やかに反応しない。よって選択肢5が誤りである。臭素の脱色を見たときは、アルケン・アルキンの付加反応と、アルカンの光置換、ベンゼンの触媒を要する置換を分ける。",
