    "question": "メチルオレンジは、ジメチルアニリンと、p－アミノベンゼンスルホン酸から得たジアゾニウム塩とのジアゾカップリングにより合成される。p－アミノベンゼンスルホン酸（ベンゼン環のパラ位に －NH₂ と －SO₃H が結合した化合物）はベンゼンを原料として、化合物XとYを経由して、3段階の反応で合成できる。\n\nベンゼン －（反応ア）→ 化合物X －（反応イ）→ 化合物Y －（反応ウ）→ p－アミノベンゼンスルホン酸\n\nこのとき用いられる反応ア、イ、ウの組合せとして最も適当なものを、次のうちから一つ選べ。ただし、ベンゼンの一置換体の置換反応は、次の性質Ⅰ〜Ⅲを示すものとする。\n\nⅠ　ベンゼンスルホン酸をニトロ化すると、m－（メタ）の位置にニトロ基が置換された化合物が生成しやすい。\nⅡ　ニトロベンゼンをスルホン化すると、m－（メタ）の位置にスルホ基が置換された化合物が生成しやすい。\nⅢ　アニリンをスルホン化すると、p－（パラ）の位置にスルホ基が置換された化合物が生成しやすい。",
    "choices": [
      "反応ア：スルホン化　／　反応イ：ニトロ化　／　反応ウ：還元",
      "反応ア：スルホン化　／　反応イ：還元　／　反応ウ：ニトロ化",
      "反応ア：ニトロ化　／　反応イ：スルホン化　／　反応ウ：還元",
      "反応ア：ニトロ化　／　反応イ：還元　／　反応ウ：スルホン化",
      "反応ア：還元　／　反応イ：スルホン化　／　反応ウ：ニトロ化",
      "反応ア：還元　／　反応イ：ニトロ化　／　反応ウ：スルホン化"
    ],
    "answer": 3,
    "explanation": "目的物のパラ位の関係を、与えられた配向性Ⅰ〜Ⅲからどの順番で置換すれば作れるかを組み立てる問題。－NH₂ はベンゼンに直接は導入できず、まずニトロ化でニトロ基 －NO₂ を入れてから還元してアミノ基にする、というのが芳香族の基本の手順である。したがって「ニトロ化」と「還元」はこの順に並び、残る「スルホン化」をどこに入れるかが問題になる。ニトロ化のあとにスルホン化すると、Ⅱよりニトロベンゼンのメタ位にスルホ基が入り、還元しても m－アミノベンゼンスルホン酸になってしまう（③は不可）。先にスルホン化してからニトロ化すると、Ⅰよりベンゼンスルホン酸のメタ位にニトロ基が入り、やはりメタ体になる（①は不可）。ニトロ化 → 還元でアニリンにしてからスルホン化すると、Ⅲよりパラ位にスルホ基が入り、目的の p－アミノベンゼンスルホン酸（スルファニル酸）が得られる。したがって④。②・⑤・⑥は「還元」がベンゼンやベンゼンスルホン酸に対して行われる順序で、還元する官能基がなく意味をなさない。「－NO₂・－SO₃H はメタ配向、－NH₂・－OH・－CH₃ はオルト・パラ配向」という配向性は、この問題では性質Ⅰ〜Ⅲとして与えられているが、覚えておけば与えられなくても判断できる。",
    "choiceNotes": [
      "誤り。先にスルホン化してベンゼンスルホン酸にし、次にニトロ化すると、性質Ⅰよりニトロ基はメタ位に入る。これを還元すると m－アミノベンゼンスルホン酸になり、目的のパラ体は得られない。",
      "誤り。ベンゼンスルホン酸には還元される官能基がないので、反応イの「還元」が成り立たない。また、仮にニトロ化を最後にしてもニトロ基が残り、アミノ基は得られない。",
      "誤り。ニトロ化してニトロベンゼンにしたあとにスルホン化すると、性質Ⅱよりスルホ基はメタ位に入る。これを還元すると m－アミノベンゼンスルホン酸になり、パラ体は得られない。",
      "正解。ベンゼンをニトロ化してニトロベンゼン（X）にし、これを還元（Sn と塩酸など）してアニリン（Y）にする。アニリンをスルホン化すると、性質Ⅲよりパラ位にスルホ基が入り、p－アミノベンゼンスルホン酸（スルファニル酸）が得られる。アミノ基はベンゼンに直接導入できないので、「ニトロ化してから還元」が基本である。",
      "誤り。ベンゼンには還元される官能基がなく、反応アの「還元」が成り立たない（ベンゼンに水素を付加すればシクロヘキサンになり、置換反応の出発物質でなくなる）。",
      "誤り。⑤と同じく、ベンゼンに対する「還元」は目的の官能基を導入する反応にならない。ニトロ基を最後まで還元しない順序でもあり、アミノ基が得られない。"
    ],
    "verifiedAt": "2026-09-13"
