    "explanation": "エステルの生成と分解の反応が可逆か不可逆かを区別できるかを問う問題。①：サリチル酸のヒドロキシ基を無水酢酸でアセチル化するとアセチルサリチル酸（解熱鎮痛薬）が生じるので正しい。②：カルボン酸とアルコールから濃硫酸を触媒としてエステルをつくる反応は平衡反応で、逆向きの加水分解も同じ触媒で進むので正しい。③：エステルはカルボン酸だけでなく、硝酸や硫酸などの無機酸とアルコールからもできる。ニトログリセリンはグリセリンの3つの －OH と硝酸がエステル結合した硝酸エステルなので正しい（名前に「ニトロ」とあるがニトロ化合物ではない）。④：塩基を用いる加水分解（けん化）では、生じたカルボン酸がただちに塩（酢酸ナトリウム）になって平衡から外れるため、反応は一方向に進む不可逆反応である。したがって④が誤り。「酸触媒の加水分解は可逆、けん化は不可逆」は油脂のけん化まで通じる基本事項である。",
