    "explanation": "フェノールからサリチル酸を経てサリチル酸メチルをつくる、芳香族化合物の定番の合成経路を問う問題。図1の下の経路は、フェノール → （Na）ナトリウムフェノキシド → （CO₂、高温・高圧）サリチル酸ナトリウム → （H⁺）サリチル酸、と進み、最後にサリチル酸のカルボキシ基をメタノールとエステル化してサリチル酸メチルを得ている。カルボン酸とアルコールのエステル化は、濃硫酸を触媒として加熱する（サリチル酸にメタノールと濃硫酸を加えて温める）ので、アは濃硫酸の④が正解。濃硫酸は酸触媒としてはたらくと同時に、生じる水を吸収して平衡をエステル側に傾ける。無水酢酸はサリチル酸のヒドロキシ基をアセチル化してアセチルサリチル酸（解熱鎮痛剤）をつくる試薬で、生成物が違う。水酸化ナトリウム水溶液ではエステルはできず塩になる。希塩酸は酸ではあるが水が多く、エステル化の触媒には使わない。二酸化炭素はすでに手前の段階（サリチル酸ナトリウムの合成）で使われている。「メタノール＋濃硫酸 → サリチル酸メチル（消炎剤）」「無水酢酸 → アセチルサリチル酸（解熱鎮痛剤）」のサリチル酸の2つの誘導体は、試薬と生成物の組合せごと覚えておく。",
