    "answer": 1,
    "explanation": "クメン法によるフェノールの工業的製法と、サリチル酸の合成（コルベ・シュミット反応）を一つの経路で問う問題。クメン法では、ベンゼンにプロペンを付加させてクメン（イソプロピルベンゼン）をつくり、空気中の O₂ で酸化してクメンヒドロペルオキシド（②、－O－OH をもつ）にする。これを希硫酸で分解すると、フェノールと同時にアセトン（④）が生じる。アセトンは副生成物ではなく、有用な溶媒として同時に生産される点がこの製法の特徴である。次に、フェノールを NaOH で中和してナトリウムフェノキシドとし、高温・高圧で二酸化炭素（⑤）を反応させるとサリチル酸ナトリウムが生じ、希硫酸を加えると弱酸のサリチル酸が遊離する。したがって A＝②、B＝④、C＝⑤。①は－OH（アルコール）で酸素の数が足りず、③の 2-プロパノールと⑥の一酸化炭素はこの経路には現れない。「クメン → ヒドロペルオキシド → フェノール＋アセトン」「フェノキシド＋CO₂ → サリチル酸」の2本を反応式で書けるようにしておく。",
