    "stemTitle": "問題文（操作Ⅰ〜Ⅲ）",
    "stem": "フェノール、サリチル酸、クメンを含むジエチルエーテル溶液（試料溶液）に、次の操作Ⅰ〜Ⅲを行うと、フェノールのみを取り出すことができた。\n\n操作Ⅰ　試料溶液に、水溶液 X を加えてよく混ぜたのち、エーテル層と水層を分離した。\n操作Ⅱ　操作Ⅰで分離したエーテル層に、水溶液 Y を加えてよく混ぜたのち、エーテル層と水層を分離した。\n操作Ⅲ　操作Ⅱで分離した水層に、水溶液 Z とジエチルエーテルを加えてよく混ぜたのち、エーテル層と水層を分離した。分離したエーテル層から、ジエチルエーテルを蒸発させるとフェノールが残った。",
