    "stem": "図1は、ベンゼンから p－ヒドロキシアゾベンゼンを合成する反応経路を示したものである。ベンゼンを濃硫酸とともに加熱すると化合物 A が生じ、A を水酸化ナトリウムで塩にしてからアルカリ融解（NaOH）すると化合物 B が生じる。一方、ベンゼンに濃硝酸と濃硫酸を作用させると化合物 C が生じ、C をスズと塩酸で処理してから水酸化ナトリウムを加えるとアニリンが生じ、アニリンに 0 ℃で亜硝酸ナトリウムと塩酸を作用させると化合物 D が生じる。B と D から p－ヒドロキシアゾベンゼンが生成する。",
