    "explanation": "ジアゾ化とジアゾカップリングを問う問題。アニリンを塩酸に溶かし、氷で冷やして 0〜5 ℃に保ちながら亜硝酸ナトリウム NaNO₂ を加えると、ジアゾ化が起こって塩化ベンゼンジアゾニウム C₆H₅N₂Cl（C₆H₅－N⁺≡N Cl⁻）が生じる。これが化合物 D で、答えは ⑧。低温にするのは、ジアゾニウム塩が温まると分解して窒素を発生し、フェノールに変わってしまうためである。D をナトリウムフェノキシド（B）の水溶液に加えると、ジアゾカップリングによって －N＝N－（アゾ基）で二つのベンゼン環がつながり、橙赤色の p－ヒドロキシアゾベンゼン（p－フェニルアゾフェノール）が生じる。これはアゾ染料の基本となる反応で、「ジアゾ化は 0 ℃・NaNO₂ ＋ HCl」「カップリングの相手はナトリウムフェノキシド」「生成物は橙赤色」をセットで覚える。",
