    "explanation": "炭素－炭素結合の種類と分子の立体構造の基本を問う問題。誤りは⑤。シクロヘキサン C₆H₁₂ は 6 個の炭素がすべて単結合でつながった環で、各炭素の結合角は正四面体に近い約 109.5° を保つため、環は平面にならず折れ曲がった「いす形」の立体構造をとる。すべての炭素原子が同一平面上にあるのはベンゼン C₆H₆（平面正六角形）であり、シクロヘキサンと混同させる典型的な引っかけである。①結合の多重度が上がるほど原子どうしは強く引き合って近づくので、C－C（約 0.154 nm）＞ C＝C（約 0.134 nm）＞ C≡C（約 0.120 nm）の順に短い。②エタンの C－C 単結合は自由に回転できる。③エチレンの C＝C 二重結合は回転できず、このために二重結合の両側の置換基の配置が固定されて、シス－トランス異性体（幾何異性体）が生じる。④アセチレン H－C≡C－H は三重結合をもつ炭素の結合角が 180° で、4 つの原子すべてが一直線上に並ぶ。エチレンは 6 原子が同一平面上にある。「エチレン＝平面、アセチレン＝直線、ベンゼン＝平面、シクロヘキサン＝いす形（非平面）」をセットで覚える。",
