    "explanation": "フェノール類の代表的な反応を、生成物の構造（どの原子とどの原子が新しくつながるか）で理解しているかを問う問題。誤りは②。濃硝酸と濃硫酸の混合物（混酸）で加熱するのはニトロ化で、ベンゼン環の水素がニトロ基 －NO₂ に置き換わり、2,4,6－トリニトロフェノール（ピクリン酸）ができる。新しくできるのは環の炭素とニトロ基の窒素の C－N 結合であり、C－S 結合ではない。C－S 結合ができるのは濃硫酸だけで加熱するスルホン化（－SO₃H が入る）である。①フェノールは臭素水を加えるだけで環の o・p 位の水素が Br に置換され、2,4,6－トリブロモフェノールの白色沈殿を生じる（C－Br）。③無水酢酸によるアセチル化では、フェノールのヒドロキシ基の O にアセチル基 CH₃CO－ が結合して酢酸フェニル（エステル）ができるので、新しくできるのはアセチル基の炭素と O の C－O 結合。④コルベ・シュミット反応では、ナトリウムフェノキシドの o 位の環炭素に CO₂ の炭素が結合してサリチル酸ナトリウムができる（C－C）。⑤ジアゾカップリングでは、フェノキシドの p 位の環炭素に塩化ベンゼンジアゾニウムの N が結合して p－ヒドロキシアゾベンゼン（橙赤色）ができる（C－N、アゾ基 －N＝N－）。「混酸はニトロ化（N）、濃硫酸だけならスルホン化（S）」の区別が決め手である。",
