    "explanation": "エタノールの脱水実験の方法と、生成するエチレンの性質を問う問題。濃硫酸にエタノールを滴下して約 170 ℃ に保つと、エタノール 1 分子から水 1 分子がとれる分子内脱水が起こり、エチレン CH₂＝CH₂ が発生する（C₂H₅OH → CH₂＝CH₂ ＋ H₂O）。適当でないのは⑤で、触媒を用いて 3 分子を重合させるとベンゼンになるのはアセチレン CH≡CH（3CH≡CH → C₆H₆）であり、エチレンではない。エチレンを重合させると高分子のポリエチレンになる。①この反応は温度で生成物が変わる（130〜140 ℃ ではジエチルエーテル、160〜170 ℃ ではエチレン）ので、反応液の温度を正確に知る必要があり、温度計の球部を液中に入れる（蒸留のときのように枝の位置に置くのではない）。②エチレンは水に溶けにくいので水上置換で捕集できる。③エチレンは 2 つの炭素が sp² 混成で、6 個の原子すべてが同一平面上にある平面構造の分子である。④エチレンを塩化パラジウム(Ⅱ)と塩化銅(Ⅱ)を触媒として酸素で酸化するとアセトアルデヒド CH₃CHO ができる（ヘキスト・ワッカー法）。エチレン（付加重合 → ポリエチレン、酸化 → アセトアルデヒド、水付加 → エタノール）とアセチレン（3 分子重合 → ベンゼン、水付加 → アセトアルデヒド、酢酸付加 → 酢酸ビニル）の反応を混同しないようにする。",
    "choiceNotes": [
      "適当。エタノールと濃硫酸の反応は温度によって生成物が変わり、130〜140 ℃ ではジエチルエーテル、160〜170 ℃ ではエチレンが生じる。反応液そのものの温度を正確に知るために、温度計の球部を濃硫酸の中に入れる。",
      "適当。発生するエチレンは無極性の分子で水にほとんど溶けないので、水槽の水と置き換えて試験管に集める水上置換で捕集できる。水に溶けやすい気体（アンモニア・塩化水素など）はこの方法では捕集できない。",
      "適当。エチレン CH₂＝CH₂ は、二重結合でつながった 2 個の炭素と 4 個の水素の計 6 個の原子がすべて同一平面上にある平面構造の分子である（エタンは立体的、アセチレンは直線形）。",
      "適当。エチレンを塩化パラジウム(Ⅱ) PdCl₂ と塩化銅(Ⅱ) CuCl₂ を触媒として酸素で酸化すると、アセトアルデヒド CH₃CHO が得られる（ヘキスト・ワッカー法。2CH₂＝CH₂ ＋ O₂ → 2CH₃CHO）。工業的なアセトアルデヒドの製法である。",
      "適当でない。触媒（赤熱した鉄など）を用いて 3 分子を重合させるとベンゼンになるのはアセチレン CH≡CH である（3CH≡CH → C₆H₆）。捕集した気体はエチレン CH₂＝CH₂ で、これを重合させるとポリエチレンになり、ベンゼンにはならない。"
    ]
