      "誤り。炭素数が増えるほど沸点が低くなる右下がりで、分子間力の傾向に反する。またオクタン（炭素数 8）が約 −160 ℃ で常温では気体ということになるが、実際のオクタンはガソリンの成分で常温では液体である。",
