    "explanation": "エタノールの酸化とアルデヒドの検出という一連の実験を、操作ごとに理解しているかを問う問題。誤りは③。エタノール CH₃CH₂OH（第一級アルコール）を硫酸酸性の二クロム酸カリウム水溶液で酸化すると、生じるのはアセトアルデヒド CH₃CHO である（CH₃CH₂OH → CH₃CHO ＋ 2H。さらに酸化すると酢酸 CH₃COOH）。ホルムアルデヒド HCHO はメタノール CH₃OH を酸化したときの生成物で、この実験では生じない。フェーリング液と反応して赤色の酸化銅(Ⅰ) Cu₂O を沈殿させたのはアセトアルデヒドである。よって③が正解。ほかは正しく、① 沸騰石（素焼きのかけらなど）は小さな気泡の核になり、液体が加熱で急に激しく沸騰する突沸を防ぐ。② アセトアルデヒドは沸点が 20 ℃ と低く揮発しやすいので、試験管 A を加熱すると蒸気として出てくる。これを氷で冷やした試験管 B の水に導き、確実に液化・溶解させて捕集する。④ 硝酸銀水溶液にアンモニア水を加えると、まず酸化銀 Ag₂O の褐色沈殿が生じる（2Ag⁺ ＋ 2OH⁻ → Ag₂O ＋ H₂O）。アンモニア水をさらに加えると、ジアンミン銀(Ⅰ)イオン [Ag(NH₃)₂]⁺ となって沈殿が溶け、無色のアンモニア性硝酸銀水溶液になる。⑤ アンモニア性硝酸銀水溶液にアルデヒドを加えて温めると、アルデヒドが酸化されるとともに Ag⁺ が還元され、試験管の内壁に銀が鏡のように析出する（銀鏡反応）。「第一級アルコールの酸化 → アルデヒド → カルボン酸（エタノール → アセトアルデヒド → 酢酸、メタノール → ホルムアルデヒド → ギ酸）」「アルデヒドの検出は銀鏡反応とフェーリング液の還元」という対応を正確に覚えておく。",
