    "explanation": "鎖式飽和炭化水素（アルカン）の基本的な性質を問う問題。誤りは①。アルカンは炭素原子が鎖状につながり、すべて単結合からなる炭化水素で、一般式は CₙH₂ₙ₊₂ で表される（メタン CH₄、エタン C₂H₆、プロパン C₃H₈ …）。CₙH₂ₙ は二重結合を 1 つもつ鎖式不飽和炭化水素（アルケン）や、環を 1 つもつシクロアルカンの一般式である。ほかは正しく、② 炭化水素は極性がほとんどない分子なので、水には溶けにくく、有機溶媒にはよく溶ける。③ 直鎖状のアルカンでは、分子量が大きいほど分子間力（ファンデルワールス力）が強くなり、沸点は高くなる（C₁〜C₄ は常温で気体、C₅〜C₁₆ 程度は液体、それ以上は固体）。④ 炭素数 4 のブタンには、直鎖のブタン CH₃－CH₂－CH₂－CH₃ と枝分かれした 2-メチルプロパン CH₃－CH(CH₃)－CH₃ の 2 種類の構造異性体がある。炭素数 3 以下には構造異性体はない。⑤ 不斉炭素原子は、異なる 4 種類の原子または原子団が結合した炭素原子である。アルカンで不斉炭素原子をもつ最小のものは炭素数 7 の 3-メチルヘキサン CH₃－CH₂－CH(CH₃)－CH₂－CH₂－CH₃ で（3 位の炭素に H・CH₃・C₂H₅・C₃H₇ の 4 種類が結合）、炭素数 6 以下のアルカンには不斉炭素原子をもつものが存在しない。「アルカン CₙH₂ₙ₊₂、アルケン・シクロアルカン CₙH₂ₙ、アルキン・シクロアルケン CₙH₂ₙ₋₂」と、不飽和度ごとに水素が 2 個ずつ減る規則で一般式を整理する。",
