    "explanation": "ベンゼン環をもつ化合物の反応が、置換反応か付加反応かを判断する問題。ベンゼン環は安定な構造なので、通常は環の水素原子がほかの原子団に置き換わる置換反応が起こり、二重結合が開いて原子が結合する付加反応は起こりにくい。付加反応が起こるのは、光（紫外線）を当てながら塩素を作用させる場合と、高温・高圧でニッケル触媒を用いて水素を作用させる場合の 2 つに限られる。② ベンゼンに光を当てながら塩素 Cl₂ を作用させると、C₆H₆ ＋ 3Cl₂ → C₆H₆Cl₆ で 3 分子の塩素が付加し、ベンゼンヘキサクロリド（1,2,3,4,5,6-ヘキサクロロシクロヘキサン、BHC）が生じる。よって②が正解。ほかはすべて置換反応（またはヒドロキシ基の反応）で、① 濃硝酸と濃硫酸の混合物（混酸）を作用させると、環の H が －NO₂ に置き換わるニトロ化でニトロベンゼンになる。③ 濃硫酸を加えて熱すると、環の H が －SO₃H に置き換わるスルホン化でベンゼンスルホン酸になる。④ フェノールに臭素水を加えると、環の H が 3 個 Br に置き換わる置換反応で 2,4,6-トリブロモフェノールの白色沈殿が生じる（フェノールの検出反応。ベンゼンと違って触媒なしで反応する）。⑤ フェノールに無水酢酸を作用させると、ヒドロキシ基の H がアセチル基 CH₃CO－ に置き換わるアセチル化（エステル化）で酢酸フェニルになる。環に対する付加ではない。ベンゼンの付加反応は「光で Cl₂ → BHC、Ni 触媒で H₂ → シクロヘキサン」の 2 つだけ、と覚え、鉄触媒で Cl₂ を作用させるとクロロベンゼンになる置換反応と区別する。",
