    "explanation": "ベンゼンからナイロン6までの合成経路を、各段階の生成物の構造まで追えるかを問う問題。触媒を用いて高温・高圧でベンゼンに水素を付加させると、二重結合がすべて飽和したシクロヘキサン C₆H₁₂（化合物D）が得られる。二重結合が 1 つ残ったシクロヘキセンにはならない。これを酸化してシクロヘキサノン、ヒドロキシルアミンとの反応を経て ε－カプロラクタムとし、ε－カプロラクタムを開環重合すると、環が開いてそのままつながるので、繰り返し単位は ε－カプロラクタムと同じ炭素数 6 の －CO－(CH₂)₅－NH－ になる。これがナイロン6（化合物E）である。炭素数 6 のアジピン酸とヘキサメチレンジアミンの縮合重合でできるナイロン66（繰り返し単位 －CO－(CH₂)₄－CO－NH－(CH₂)₆－NH－）との区別が最大のポイントで、「ナイロン6は 1 種類の原料の開環重合、ナイロン66は 2 種類の原料の縮合重合」と覚える。",
