      "正しい。陰イオン交換樹脂は塩基性の基（－N⁺(CH₃)₃OH⁻ など）をもち、水中の陰イオンと OH⁻ を交換する。使用後は強塩基（NaOH 水溶液）で処理して OH⁻ 型に戻すことで再生できる。",
