    "explanation": "合成高分子の重合のしくみ（付加重合と縮合重合）と用途を問う問題。誤りは①。ポリ塩化ビニルは、塩化ビニル CH₂＝CHCl の C＝C 二重結合が次々に開いてつながる付加重合によって生成する（n CH₂＝CHCl → [－CH₂－CHCl－]ₙ）。縮合重合は、2 種類（または 1 種類）の単量体の間から水などの小さな分子がとれながらつながる重合で、ナイロン 66 やポリエチレンテレフタラートがその例である。塩化ビニルには水がとれるような官能基がなく、二重結合をもつので付加重合する。よって正しくは「付加重合」で、①が正解。ほかは正しく、② 付加重合では単量体の原子がすべて高分子に残るので、ポリ塩化ビニルの繰り返し単位 －CH₂－CHCl－ には塩化ビニル由来の C－Cl 結合がそのまま含まれる。③ ポリ塩化ビニルは硬く燃えにくく耐薬品性があり、加熱して成形（成型）加工され、水道管・雨どい・電線の被覆・シートなどに広く使われる。④ ナイロン 66 は、アジピン酸 HOOC－(CH₂)₄－COOH とヘキサメチレンジアミン H₂N－(CH₂)₆－NH₂ が縮合重合し、カルボキシ基とアミノ基の間から水がとれてアミド結合 －CO－NH－ でつながった高分子である（66 は炭素数がそれぞれ 6 であることを表す）。⑤ ナイロン 66 は絹に似た丈夫な合成繊維で、衣料・釣り糸・ロープなどに使われる。「二重結合をもつ単量体（エチレン・塩化ビニル・スチレン・プロピレンなど）→ 付加重合」「－COOH と －NH₂、－COOH と －OH のように 2 つの官能基が反応して水がとれる → 縮合重合（ナイロン・ポリエステル）」の分け方は最頻出である。",
